add({
  name: "web_search",
  description:
    "Search the live web and get a synthesized answer with sources. Use for current events, docs, or anything outside your knowledge.",
  args: `{"query": string}`,
  needsApproval: false,
  subagentSafe: true,
  run: async (args) => {
    const query = str(args, "query");
    const { chat } = await import("./groq.ts");
    const { SUBAGENT_MODEL } = await import("./config.ts");
    const res = await chat(
      [
        {
          role: "user",
          content: `Search the web and answer concisely with source URLs: ${query}`,
        },
      ],
      { model: SUBAGENT_MODEL, enabledTools: ["web_search", "visit_website"], maxTokens: 2048 },
    );
    return cap(res.content);
  },
});

